<?php
require_once dirname(__DIR__) . '/config/config.php'; require_once dirname(__DIR__) . '/includes/functions.php'; requireAdminLogin();
$db = getDB(); $db->exec("CREATE TABLE IF NOT EXISTS product_source_drafts (id INT UNSIGNED AUTO_INCREMENT PRIMARY KEY, category_id INT UNSIGNED NOT NULL, source_brand VARCHAR(40) NOT NULL, source_url VARCHAR(500) NOT NULL UNIQUE, name VARCHAR(180) NOT NULL, slug VARCHAR(200) NOT NULL, short_desc VARCHAR(300) DEFAULT NULL, raw_json MEDIUMTEXT DEFAULT NULL, status ENUM('pending','imported','rejected','duplicate') NOT NULL DEFAULT 'pending', created_at DATETIME DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, INDEX(category_id), INDEX(status), INDEX(slug)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4");
if ($_SERVER['REQUEST_METHOD'] === 'POST') { verifyCsrf(); $id=(int)($_POST['id']??0); $action=$_POST['action']??''; $draft=$db->prepare('SELECT * FROM product_source_drafts WHERE id=?'); $draft->execute([$id]); $draft=$draft->fetch(); if ($draft && $draft['status']==='pending') { if ($action==='reject') { $db->prepare("UPDATE product_source_drafts SET status='rejected' WHERE id=?")->execute([$id]); setFlash('success','Draft rejected.'); } elseif ($action==='import') { $exists=$db->prepare('SELECT id FROM products WHERE slug=? OR name=? LIMIT 1'); $exists->execute([$draft['slug'],$draft['name']]); if ($exists->fetch()) { $db->prepare("UPDATE product_source_drafts SET status='duplicate' WHERE id=?")->execute([$id]); setFlash('warning','Existing product found; draft marked duplicate.'); } else { $metaTitle=mb_substr($draft['name'].' in Karachi | '.SITE_NAME,0,180); $metaDesc=mb_substr(($draft['short_desc']?:$draft['name']).' Available from '.SITE_NAME.' in Karachi.',0,300); $db->prepare("INSERT INTO products (category_id,name,slug,brand,short_desc,description,price,stock_status,featured,status,meta_title,meta_description,product_type) VALUES (?,?,?,?,?,?,0,'in_stock',0,'inactive',?,?, 'other')")->execute([$draft['category_id'],$draft['name'],$draft['slug'],ucfirst($draft['source_brand']),$draft['short_desc']?:null,$draft['short_desc']?:null,$metaTitle,$metaDesc]); $db->prepare("UPDATE product_source_drafts SET status='imported' WHERE id=?")->execute([$id]); setFlash('success','Product added as inactive with price 0. Add verified details and price before publishing.'); } } } header('Location: '.ADMIN_URL.'/product-source-drafts.php'); exit; }
$drafts=$db->query("SELECT d.*, c.name category_name FROM product_source_drafts d LEFT JOIN categories c ON c.id=d.category_id WHERE d.status='pending' ORDER BY d.id DESC")->fetchAll(); $adminPageTitle='Review Product Drafts'; include __DIR__.'/includes/header.php';
?>
<div class="admin-page-header"><h1 class="admin-page-title"><i class="fa-solid fa-list me-2"></i>Review Product Drafts</h1><a href="<?= ADMIN_URL ?>/product-source-search.php" class="btn-admin-primary"><i class="fa-solid fa-magnifying-glass me-1"></i>New Search</a></div><?php showFlash(); ?><div class="admin-card"><div class="admin-card-body p-0"><div class="table-responsive"><table class="admin-table"><thead><tr><th>Product</th><th>Brand</th><th>Category</th><th>Official source</th><th>Actions</th></tr></thead><tbody><?php foreach($drafts as $draft): ?><tr><td><strong><?=h($draft['name'])?></strong><br><small class="text-muted"><?=h($draft['short_desc']??'No snippet returned')?></small></td><td><?=h(ucfirst($draft['source_brand']))?></td><td><?=h($draft['category_name']??'—')?></td><td><a href="<?=h($draft['source_url'])?>" target="_blank" rel="noopener noreferrer">Verify source <i class="fa-solid fa-arrow-up-right-from-square"></i></a></td><td><form method="POST" class="d-inline"><?php csrfField(); ?><input type="hidden" name="id" value="<?=$draft['id']?>"><button name="action" value="import" class="btn-admin-primary btn-sm">Import Draft</button><button name="action" value="reject" class="btn-admin-outline btn-sm ms-1">Reject</button></form></td></tr><?php endforeach; if(!$drafts): ?><tr><td colspan="5" class="text-center py-4 text-muted">No pending drafts.</td></tr><?php endif; ?></tbody></table></div></div></div><?php include __DIR__.'/includes/footer.php'; ?>
